    rad *= x2;
    s += rad * -0.16666656732559204f;
    rad *= x2;
    s += rad * 0.008333025500178337f;
    rad *= x2;
    s += rad * -0.00019807413627859205f;
    rad *= x2;
    s += rad * 2.601886990305502e-06f;
    s = GClamp(s, -1.0f, 1.0f);
    c = SqrtS(1.0f - s * s);
    if (n & 1)
        c = -c;
    *pcos = c;
    *psin = s;
